Recall@k.ejemplo:
def recall_at_k(relevant_ids: set[str], retrieved_ids: list[str], k: int) -> float:
    if not relevant_ids:
        return 0.0
    hits = len(relevant_ids.intersection(retrieved_ids[:k]))
    return hits / len(relevant_ids)

# relevant={"doc2", "doc5"}, top-3=["doc1", "doc2", "doc4"] -> 1/2 = 0.5

