import numpy as np
# u, v: embeddings de "Cancela mi suscripción" y "Dar de baja el plan"
def cosine_sim(u: np.ndarray, v: np.ndarray) -> float:
    return float(np.dot(u, v) / (np.linalg.norm(u) * np.linalg.norm(v)))
