def route_prediction(prob_fraud: float, t_low=0.25, t_high=0.85) -> str:
    if prob_fraud >= t_high:
        return "BLOCK"
    if prob_fraud >= t_low:
        return "HUMAN_REVIEW"
    return "APPROVE"
